#!/usr/bin/env node
// medtech-data.mjs — zero-dependency CLI for public healthcare data APIs:
// CMS data.cms.gov (claims, catalog, enrollment, Provider Data Catalog),
// NPPES, Open Payments, openFDA and the Census API.
//
// SOURCE OF TRUTH: plugins/medtech-market-data/src/medtech-data.mjs. Each
// skill's scripts/ copy is generated by build.mjs — edit this file, not those.
// Node 18+ (global fetch). Data goes to stdout; diagnostics go to stderr.
// Run `node medtech-data.mjs help` for usage. Each skill's SKILL.md documents
// the API rules this script enforces and why.

import { mkdirSync, readFileSync, writeFileSync, statSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { realpathSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

if (typeof fetch !== 'function') {
  console.error(`medtech-data.mjs needs Node 18+ (global fetch); this is ${process.version}`);
  process.exit(1);
}

// Node's built-in fetch ignores HTTPS_PROXY unless NODE_USE_ENV_PROXY=1 (Node
// >= 22.21). Behind a proxy, the CLI re-runs itself once with it set so every
// host goes through the proxy. Only when run as a CLI, never on import.
function reexecWithEnvProxy() {
  const proxy = process.env.HTTPS_PROXY || process.env.https_proxy;
  const [major, minor] = process.versions.node.split('.').map(Number);
  if (!proxy || process.env.NODE_USE_ENV_PROXY || !(major > 22 || (major === 22 && minor >= 21))) return false;
  const r = spawnSync(process.execPath, [...process.execArgv, ...process.argv.slice(1)], {
    stdio: 'inherit', env: { ...process.env, NODE_USE_ENV_PROXY: '1', NODE_NO_WARNINGS: '1' },
  });
  process.exit(r.status ?? 1);
}

const CATALOG_URL = 'https://data.cms.gov/data.json';
const DATA_API = 'https://data.cms.gov/data-api/v1/dataset';
const PD_API = 'https://data.cms.gov/provider-data/api/1';
const NPPES_API = 'https://npiregistry.cms.hhs.gov/api/';
const OP_API = 'https://openpaymentsdata.cms.gov/api/1';
const CACHE_DIR = join(tmpdir(), 'medtech-market-data');
const CATALOG_INDEX = join(CACHE_DIR, 'catalog-index.json');
const CATALOG_TTL_MS = 24 * 3600 * 1000;
const PAGE_SIZE = 1000;      // data-api page size; 5000 also works, but 1000 is reliable
const PD_PAGE_SIZE = 1500;   // provider-data hard max (400 above this)
const OP_PAGE_SIZE = 500;    // Open Payments hard max ("JSON Schema validation failed" above this; verified 2026-10-27)
const TIMEOUT_MS = 90000;    // provider-data queries take ~15s each, flat
// The CMS edge 403s Node's default User-Agent ("node") on provider-data
// (verified 2026-10-26; curl's default passes). Identify the tool honestly.
const USER_AGENT = 'medtech-market-data/1.0 (+https://github.com/jdef11/medintel)';

// Short names for the families most sales/market questions need. Any other
// catalog title (or a dataset UUID) works too.
const FAMILIES = {
  provider:     'Medicare Physician & Other Practitioners - by Provider and Service',
  provSummary:  'Medicare Physician & Other Practitioners - by Provider',
  geography:    'Medicare Physician & Other Practitioners - by Geography and Service',
  inpProvider:  'Medicare Inpatient Hospitals - by Provider and Service',
  inpGeo:       'Medicare Inpatient Hospitals - by Geography and Service',
  dmeGeo:       'Medicare Durable Medical Equipment, Devices & Supplies - by Geography and Service',
  dmeReferring: 'Medicare Durable Medical Equipment, Devices & Supplies - by Referring Provider and Service',
  outProvider:  'Medicare Outpatient Hospitals - by Provider and Service',
  outGeo:       'Medicare Outpatient Hospitals - by Geography and Service',
  enrollment:   'Medicare Monthly Enrollment',
};

// Families published as ONE rolling dataset; the data year is a column.
const ROLLING = { enrollment: 'YEAR' };

// "latest" alias UUIDs (taken from data.json 2026-10-09). Used only when the
// catalog can't be loaded; CMS moves each alias to the newest year.
const LATEST_IDS = {
  provider:     '92396110-2aed-4d63-a6a2-5d6207d46a29',
  provSummary:  '8889d81e-2ee7-448f-8713-f071038289b5',
  geography:    '6fea9d79-0129-4e4c-b1b8-23cd86a4f435',
  inpProvider:  '690ddc6c-2767-4618-b277-420ffb2bf27c',
  inpGeo:       '2941ab09-8cee-49d8-9703-f3c5b854e388',
  dmeGeo:       '27c150fd-8578-43b1-bba5-6388987e32af',
  dmeReferring: '86b4807a-d63a-44be-bfdf-ffd398d5e623',
};

const PD_ALIASES = {
  clinicians: 'mj5m-pzi6',    // Doctors and Clinicians National Downloadable File (org_pac_id)
  facilityAff: '27ea-46a8',   // Facility Affiliation Data (NPI -> facility CCN)
  hospitals: 'xubh-q36u',     // Hospital General Information (CCN -> name, rating)
};

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const log = (...a) => console.error(...a);
const die = (msg, code = 1) => { log(`error: ${msg}`); process.exit(code); };

// ─── HTTP ───

// Text (not JSON) GET, e.g. Census CSVs, which are Latin-1 encoded.
function getText(url, { encoding = 'utf-8', retries = 2 } = {}) {
  return getJson(url, { retries, text: encoding });
}

async function getJson(url, { retries = 2, text: textEncoding = null } = {}) {
  for (let attempt = 0; ; attempt++) {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), TIMEOUT_MS);
    let res, text;
    try {
      res = await fetch(url, { signal: ctrl.signal, headers: { accept: textEncoding ? '*/*' : 'application/json', 'user-agent': USER_AGENT } });
      text = new TextDecoder(textEncoding || 'utf-8').decode(await res.arrayBuffer());
    } catch (e) {
      clearTimeout(t);
      if (attempt < retries) { await sleep(2000 * 2 ** attempt); continue; }
      throw new Error(`${e.name === 'AbortError' ? 'timed out' : e.message} — ${url}`);
    }
    clearTimeout(t);
    if ((res.status === 429 || res.status >= 500) && attempt < retries) {
      await sleep(2000 * 2 ** attempt);
      continue;
    }
    if (/^\s*<html/i.test(text) && /Access Denied/i.test(text)) {
      throw new Error(`HTTP ${res.status} "Access Denied" from the CMS edge (Akamai) — this host is refusing ` +
        `this client/network. Not a data answer and not a bad query. Do not retry in a loop or spoof headers; ` +
        `report it and try another network. URL: ${url}`);
    }
    if (textEncoding) {
      if (!res.ok) throw new Error(`HTTP ${res.status} — ${url}`);
      return text;
    }
    let body;
    try { body = JSON.parse(text); } catch {
      throw new Error(`HTTP ${res.status}, non-JSON response (${text.slice(0, 160).replace(/\s+/g, ' ')}) — ${url}`);
    }
    if (!res.ok) {
      const e = body && (body.message || body.error);
      const m = e ? (typeof e === 'object' ? JSON.stringify(e) : e) : JSON.stringify(body).slice(0, 200);
      throw new Error(`HTTP ${res.status}: ${m} — ${url}`);
    }
    return body;
  }
}

const sleep = ms => new Promise(r => setTimeout(r, ms));

// ─── CATALOG (data.json → family title → [{year, id}]) ───

// Same rules as MedIntel's extractDatasetVersions(): handles the legacy shape
// and DCAT-US 3.0 (one entry per year titled "<family> : <release date>",
// linked by inSeries, year from temporal.startDate — NOT the title's date),
// and prefers the version-pinned UUID over the moving "latest" alias.
export function buildCatalogIndex(catalog) {
  const datasets = Array.isArray(catalog && catalog.dataset) ? catalog.dataset : [];
  const uuidFromUrl = url => {
    const m = String(url || '').match(/data-api\/v1\/dataset\/([0-9a-f-]{36})/i);
    return m ? m[1] : null;
  };
  const yearFrom = (...c) => {
    for (const v of c) { const m = String(v || '').match(/(20\d{2})/); if (m) return +m[1]; }
    return null;
  };
  const temporalYear = t => {
    for (const p of (Array.isArray(t) ? t : [t])) {
      const y = (p && typeof p === 'object') ? yearFrom(p.startDate, p.endDate) : yearFrom(p);
      if (y) return y;
    }
    return null;
  };
  const familyOf = ds => {
    const series = Array.isArray(ds.inSeries) ? ds.inSeries : (ds.inSeries ? [ds.inSeries] : []);
    const s = series.find(x => x && x.title);
    if (s) return s.title.trim();
    return String(ds.title || '').replace(/\s*:\s*\d{4}-\d{2}-\d{2}\s*$/, '').trim();
  };

  const families = {};
  for (const ds of datasets) {
    if (!ds || !ds.title) continue;
    const fam = familyOf(ds);
    const dists = Array.isArray(ds.distribution) ? ds.distribution : [];
    const byYear = families[fam] || (families[fam] = {});
    const dsYear = temporalYear(ds.temporal);
    if (dsYear) {
      const ids = dists
        .map(d => ({ id: uuidFromUrl(d.accessURL) || uuidFromUrl(d.downloadURL), latest: /latest/i.test(String(d.description || '')) }))
        .filter(d => d.id);
      const pick = ids.find(d => !d.latest) || ids[0];
      if (pick && !byYear[dsYear]) byYear[dsYear] = pick.id;
      continue;
    }
    for (const d of dists) {
      const id = uuidFromUrl(d.accessURL) || uuidFromUrl(d.downloadURL);
      const y = temporalYear(d.temporal) || yearFrom(d.title, d.description);
      if (id && y && !byYear[y]) byYear[y] = id;
    }
  }
  const out = {};
  for (const [fam, byYear] of Object.entries(families)) {
    const versions = Object.entries(byYear).map(([year, id]) => ({ year: +year, id })).sort((a, b) => b.year - a.year);
    if (versions.length) out[fam] = versions;
  }
  return out;
}

let catalogIndexMemo = null;
async function loadCatalogIndex({ refresh = false } = {}) {
  if (catalogIndexMemo) return catalogIndexMemo;
  if (!refresh) {
    try {
      if (Date.now() - statSync(CATALOG_INDEX).mtimeMs < CATALOG_TTL_MS) {
        return (catalogIndexMemo = JSON.parse(readFileSync(CATALOG_INDEX, 'utf8')));
      }
    } catch { /* no cache */ }
  }
  log('loading data.cms.gov/data.json (~18 MB, cached 24h)…');
  const index = buildCatalogIndex(await getJson(CATALOG_URL));
  if (!Object.keys(index).length) throw new Error('data.json loaded but no dataset families with data-api versions were found — catalog format may have changed');
  try { mkdirSync(CACHE_DIR, { recursive: true }); writeFileSync(CATALOG_INDEX, JSON.stringify(index)); } catch { /* cache is optional */ }
  return (catalogIndexMemo = index);
}

// ─── DATASET RESOLUTION ───

// Resolve a family alias / catalog title / title fragment / UUID (+ optional
// year) to { id, year, title, note }.
async function resolveDataset(spec, year) {
  if (!spec) die('dataset required (alias like "provider", a catalog title, or a dataset UUID)');
  if (UUID_RE.test(spec)) {
    if (year) log('note: --year is ignored when a UUID is given (a UUID already names one year)');
    return { id: spec, year: null, title: null };
  }
  const aliasKey = Object.keys(FAMILIES).find(k => k.toLowerCase() === spec.toLowerCase());
  if (aliasKey && ROLLING[aliasKey] && year) die(`${aliasKey} is one rolling dataset; filter the year with --where ${ROLLING[aliasKey]}=${year} instead of --year`);
  const title = aliasKey ? FAMILIES[aliasKey] : spec;
  let index;
  try {
    index = await loadCatalogIndex();
  } catch (e) {
    const alias = Object.keys(FAMILIES).find(k => FAMILIES[k] === title);
    if (alias && !year && LATEST_IDS[alias]) {
      log(`warning: catalog unavailable (${e.message}); using the "latest" alias for ${alias}. Year unknown until fetched; no history available.`);
      return { id: LATEST_IDS[alias], year: null, title, note: 'latest-alias fallback' };
    }
    throw e;
  }
  const norm = s => s.toLowerCase().replace(/\s+/g, ' ').trim();
  let fam = Object.keys(index).find(t => norm(t) === norm(title));
  if (!fam) {
    const hits = Object.keys(index).filter(t => norm(t).includes(norm(spec)));
    if (hits.length === 1) fam = hits[0];
    else if (hits.length > 1) die(`"${spec}" matches ${hits.length} dataset families — be more specific:\n  ${hits.slice(0, 25).join('\n  ')}`);
    else die(`no dataset family matches "${spec}". Try: node medtech-data.mjs datasets --search <words>`);
  }
  const versions = index[fam];
  const v = year ? versions.find(x => x.year === +year) : versions[0];
  if (!v) die(`"${fam}" has no ${year} version. Available: ${versions.map(x => x.year).join(', ')}`);
  return { id: v.id, year: v.year, title: fam };
}

// Column names + source file for a data-api dataset version (cheap: size=0).
const metaMemo = new Map();
async function datasetMeta(id) {
  if (metaMemo.has(id)) return metaMemo.get(id);
  const j = await getJson(`${DATA_API}/${id}/data-viewer?size=0`);
  const m = (j && j.meta) || {};
  const file = m.data_file_name || '';
  const fy = file.match(/(?:^|_)DY?(\d{2})(?=[_.])/i);
  const meta = { headers: m.headers || [], file, fileYear: fy ? 2000 + +fy[1] : null, totalRows: m.total_rows };
  metaMemo.set(id, meta);
  return meta;
}

// ─── DATA-API FILTERS ───

// --where expressions: Col=val, Col!=val, Col~val (CONTAINS), Col^val
// (STARTS_WITH), Col>n, Col>=n, Col<n, Col<=n. --in Col=a,b,c.
const WHERE_RE = /^([A-Za-z0-9_ ]+?)\s*(!=|>=|<=|=|~|\^|>|<)\s*(.*)$/;
const OP_MAP = { '=': '=', '!=': '<>', '~': 'CONTAINS', '^': 'STARTS_WITH', '>': '>', '>=': '>=', '<': '<', '<=': '<=' };

export function parseWhere(expr) {
  const m = String(expr).match(WHERE_RE);
  if (!m) throw new Error(`can't parse --where "${expr}" (use Col=val, Col!=val, Col~text, Col^prefix, Col>n …)`);
  return { path: m[1].trim(), op: OP_MAP[m[2]], value: m[3] };
}

export function parseIn(expr) {
  const i = String(expr).indexOf('=');
  if (i < 1) throw new Error(`can't parse --in "${expr}" (use Col=a,b,c)`);
  const values = expr.slice(i + 1).split(',').map(s => s.trim()).filter(Boolean);
  if (!values.length) throw new Error(`--in "${expr}" has no values`);
  return { path: expr.slice(0, i).trim(), op: 'IN', value: values };
}

// Always an explicit AND group when there are 2+ conditions. CMS has combined a
// bare list of conditions as OR in the past; the explicit group is unambiguous.
export function buildDataApiFilter(conds) {
  const enc = encodeURIComponent;
  const one = (label, c, group) => {
    let p = `filter[${label}][condition][path]=${enc(c.path)}&filter[${label}][condition][operator]=${enc(c.op)}`;
    if (Array.isArray(c.value)) p += c.value.map(v => `&filter[${label}][condition][value][]=${enc(v)}`).join('');
    else p += `&filter[${label}][condition][value]=${enc(c.value)}`;
    if (group) p += `&filter[${label}][condition][memberOf]=${group}`;
    return p;
  };
  if (!conds.length) return '';
  if (conds.length === 1) return one('c0', conds[0]);
  return [`filter[g][group][conjunction]=AND`, ...conds.map((c, i) => one(`c${i}`, c, 'g'))].join('&');
}

// The data-api silently IGNORES a filter/sort on a column that doesn't exist
// and returns unfiltered rows. Check every referenced column against the real
// header list first.
function checkColumns(headers, names, ctx) {
  if (!headers.length) { log('warning: could not read column list; column names are unverified'); return; }
  for (const n of names) {
    if (headers.includes(n)) continue;
    const ci = headers.find(h => h.toLowerCase() === n.toLowerCase());
    const near = headers.filter(h => h.toLowerCase().includes(n.toLowerCase().replace(/^.*_/, ''))).slice(0, 6);
    die(`column "${n}" (${ctx}) does not exist in this dataset. ` +
      (ci ? `Did you mean "${ci}"? (names are case-sensitive in filters) ` : '') +
      (near.length && !ci ? `Similar: ${near.join(', ')}. ` : '') +
      `Run: node medtech-data.mjs columns <dataset>`);
  }
}

// ─── OUTPUT ───

function emit(rows, format) {
  if (format === 'csv') {
    const cols = [...rows.reduce((s, r) => { Object.keys(r).forEach(k => s.add(k)); return s; }, new Set())];
    const esc = v => {
      const s = v == null ? '' : (typeof v === 'object' ? JSON.stringify(v) : String(v));
      return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    };
    process.stdout.write([cols.join(','), ...rows.map(r => cols.map(c => esc(r[c])).join(','))].join('\n') + '\n');
  } else if (format === 'ndjson') {
    process.stdout.write(rows.map(r => JSON.stringify(r)).join('\n') + (rows.length ? '\n' : ''));
  } else {
    process.stdout.write(JSON.stringify(rows, null, 2) + '\n');
  }
}

// ─── ARG PARSING ───

function parseArgs(argv) {
  const out = { _: [], where: [], in: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (!a.startsWith('--')) { out._.push(a); continue; }
    const [k, inline] = a.slice(2).split(/=(.*)/s);
    const takesValue = !['all', 'count', 'refresh', 'url', 'help', 'raw', 'full', 'pop65', 'by-county'].includes(k);
    const v = takesValue ? (inline !== undefined ? inline : argv[++i]) : true;
    if (takesValue && v === undefined) die(`--${k} needs a value`);
    if (k === 'where' || k === 'in') out[k].push(v); else out[k] = v;
  }
  return out;
}

const intArg = (v, name, dflt) => {
  if (v === undefined) return dflt;
  const n = Number(v);
  if (!Number.isInteger(n) || n < 0) die(`--${name} must be a non-negative integer`);
  return n;
};

// ─── COMMANDS ───

async function cmdDatasets(a) {
  const index = await loadCatalogIndex({ refresh: !!a.refresh });
  const q = a.search ? String(a.search).toLowerCase().split(/\s+/) : [];
  const rows = Object.entries(index)
    .filter(([t]) => q.every(w => t.toLowerCase().includes(w)))
    .map(([title, v]) => ({
      alias: Object.keys(FAMILIES).find(k => FAMILIES[k] === title) || '',
      title, years: v.map(x => x.year).join(','), latestId: v[0].id,
    }))
    .sort((x, y) => (y.alias ? 1 : 0) - (x.alias ? 1 : 0) || x.title.localeCompare(y.title));
  emit(rows, a.format || 'json');
  log(`${rows.length} dataset famil${rows.length === 1 ? 'y' : 'ies'}`);
}

async function cmdVersions(a) {
  const spec = a._[0];
  if (UUID_RE.test(spec || '')) die('versions takes a family alias or title, not a UUID');
  const r = await resolveDataset(spec);
  const index = await loadCatalogIndex();
  emit(index[r.title].map(v => ({ year: v.year, id: v.id })), a.format || 'json');
  log(r.title);
}

async function cmdColumns(a) {
  const r = await resolveDataset(a._[0], a.year);
  const m = await datasetMeta(r.id);
  log(`${r.title || r.id} — CY${r.year || m.fileYear || '?'} — ${m.file} — ${m.totalRows} rows`);
  process.stdout.write(m.headers.join('\n') + '\n');
}

async function cmdQuery(a) {
  const r = await resolveDataset(a._[0], a.year);
  const meta = await datasetMeta(r.id);
  const year = r.year || meta.fileYear;
  if (r.year && meta.fileYear && r.year !== meta.fileYear) {
    log(`warning: catalog says CY${r.year} but the data file is ${meta.file} (CY${meta.fileYear})`);
  }
  let conds;
  try { conds = [...a.where.map(parseWhere), ...a.in.map(parseIn)]; } catch (e) { die(e.message); }
  const columns = a.columns ? String(a.columns).split(',').map(s => s.trim()).filter(Boolean) : [];
  const sortCol = a.sort ? String(a.sort).replace(/^-/, '') : null;
  checkColumns(meta.headers, [...conds.map(c => c.path), ...columns, ...(sortCol ? [sortCol] : [])], 'filter/column/sort');

  const filter = buildDataApiFilter(conds);
  const base = `${DATA_API}/${r.id}/data`;
  const statsUrl = `${base}/stats${filter ? '?' + filter : ''}`;
  const stats = await getJson(statsUrl);
  const found = stats.found_rows;
  log(`${r.title || r.id} | CY${year || '?'} | ${r.id}${r.note ? ' | ' + r.note : ''}`);
  log(`matching rows: ${found} of ${stats.total_rows}`);
  if (a.count) { process.stdout.write(JSON.stringify({ dataset: r.title, year, id: r.id, found_rows: found, total_rows: stats.total_rows }) + '\n'); return; }

  const want = a.all ? intArg(a.max, 'max', 50000) : intArg(a.limit, 'limit', 100);
  const start = intArg(a.offset, 'offset', 0);
  const extra = [
    columns.length ? `column=${columns.map(encodeURIComponent).join(',')}` : '',
    a.sort ? `sort=${encodeURIComponent(a.sort)}` : '',
  ].filter(Boolean).join('&');

  const rows = [];
  let offset = start;
  while (rows.length < want) {
    const size = Math.min(PAGE_SIZE, want - rows.length);
    const qs = [filter, extra, `size=${size}`, `offset=${offset}`].filter(Boolean).join('&');
    const url = `${base}?${qs}`;
    if (a.url) log(url);
    const page = await getJson(url);
    if (!Array.isArray(page)) die(`unexpected response shape (not an array) from ${url}`);
    rows.push(...page);
    offset += page.length;
    if (page.length < size) break;
    if (rows.length && rows.length % 5000 === 0) log(`  …${rows.length} rows`);
  }
  emit(rows, a.format || 'json');
  const remaining = found - start - rows.length;
  log(`returned ${rows.length} row(s)` + (remaining > 0 ? ` — ${remaining} more match (raise --limit, or --all [--max N])` : ''));
}

// ─── DKAN HOSTS (Provider Data Catalog, Open Payments) ───
// Both run DKAN: {results, count, schema}; unknown columns → HTTP 400 "Column
// not found" (unlike data-api); `in` values MUST be repeated value[] params (a
// comma-joined string silently returns zero rows). Query by distribution UUID
// (/datastore/query/{distId}), resolved from the metastore, rather than
// /datastore/query/{datasetId}/0: the CMS edge 403s the latter for mj5m-pzi6
// (verified 2026-10-26). Distribution ids change when CMS refreshes a dataset,
// so they're looked up each run.
async function dkanQueryBase(host, id) {
  try {
    const j = await getJson(`${host}/metastore/schemas/dataset/items/${id}?show-reference-ids`);
    const dist = Array.isArray(j.distribution) && j.distribution[0] && j.distribution[0].identifier;
    if (dist) return { base: `${host}/datastore/query/${dist}`, title: j.title };
    log(`warning: no distribution listed for ${id}; using /datastore/query/${id}/0`);
  } catch (e) {
    log(`warning: metastore lookup for ${id} failed (${e.message}); using /datastore/query/${id}/0`);
  }
  return { base: `${host}/datastore/query/${id}/0`, title: null };
}

function dkanParams(a) {
  const enc = encodeURIComponent;
  const parts = [];
  let i = 0;
  for (const w of a.where) {
    const m = String(w).match(/^([A-Za-z0-9_]+)\s*(!=|>=|<=|=|~|>|<)\s*(.*)$/);
    if (!m) die(`can't parse --where "${w}"`);
    const op = { '=': '=', '!=': '<>', '>': '>', '>=': '>=', '<': '<', '<=': '<=', '~': 'LIKE' }[m[2]];
    const val = m[2] === '~' ? `%${m[3]}%` : m[3];
    parts.push(`conditions[${i}][property]=${enc(m[1])}&conditions[${i}][value]=${enc(val)}&conditions[${i}][operator]=${enc(op)}`);
    i++;
  }
  for (const expr of a.in) {
    let c; try { c = parseIn(expr); } catch (e) { die(e.message); }
    parts.push(`conditions[${i}][property]=${enc(c.path)}` + c.value.map(v => `&conditions[${i}][value][]=${enc(v)}`).join('') + `&conditions[${i}][operator]=in`);
    i++;
  }
  if (a.columns) String(a.columns).split(',').forEach(p => parts.push(`properties[]=${enc(p.trim())}`));
  if (a.sort) {
    const desc = String(a.sort).startsWith('-');
    parts.push(`sorts[0][property]=${enc(String(a.sort).replace(/^-/, ''))}&sorts[0][order]=${desc ? 'desc' : 'asc'}`);
  }
  return parts;
}

// Sort rows by a column: numerically when every non-empty value is a number,
// else as text. Used where the server stores numbers as text (Open Payments
// amounts), so its own sort is alphabetical ("9975.00" > "77857879.56").
const MISSING = /^\s*(|not available|n\/a|na|--|\*)\s*$/i;
export function sortRows(rows, spec) {
  const desc = String(spec).startsWith('-');
  const col = String(spec).replace(/^-/, '');
  const present = rows.map(r => r[col]).filter(v => v != null && !MISSING.test(String(v)));
  // Numeric when every real value is a number; placeholders ("Not Available", "N/A", blank) sort last either way.
  const numeric = present.length > 0 && present.every(v => Number.isFinite(Number(v)));
  const missing = r => r[col] == null || MISSING.test(String(r[col]));
  return [...rows].sort((x, y) => {
    const mx = missing(x), my = missing(y);
    if (mx || my) return mx === my ? 0 : mx ? 1 : -1;
    const c = numeric ? Number(x[col]) - Number(y[col]) : String(x[col]).localeCompare(String(y[col]));
    return desc ? -c : c;
  });
}

// opts.clientSort: the server's sort can't be trusted (text-typed numbers), so
// fetch every match (up to --max), sort here, then apply --limit.
async function runDkan(base, a, label, pageSize = PD_PAGE_SIZE, opts = {}) {
  const clientSort = opts.clientSort && a.sort && !a.count;
  const parts = dkanParams(clientSort ? { ...a, sort: undefined } : a);
  const limitArg = intArg(a.limit, 'limit', 100);
  const want = a.count ? 1 : (a.all || clientSort) ? intArg(a.max, 'max', 20000) : limitArg;
  let offset = intArg(a.offset, 'offset', 0);
  let rows = [];
  let count = null;
  log(label);
  while (rows.length < want) {
    const limit = Math.min(pageSize, want - rows.length);
    const url = `${base}?${[...parts, `limit=${limit}`, `offset=${offset}`].join('&')}`;
    if (a.url) log(url);
    const j = await getJson(url);
    if (!j || !Array.isArray(j.results)) die(`unexpected response shape from ${url}`);
    count = j.count;
    rows.push(...j.results);
    offset += j.results.length;
    if (j.results.length < limit) break;
  }
  if (a.count) { process.stdout.write(JSON.stringify({ count }) + '\n'); return; }
  if (clientSort) {
    if (count > rows.length) {
      log(`warning: sorted only the first ${rows.length} of ${count} matches (raise --max, or narrow the filters / use a grouped table); the top rows may be wrong`);
    }
    rows = sortRows(rows, a.sort);
    if (!a.all) rows = rows.slice(0, limitArg);
  }
  emit(rows, a.format || 'json');
  log(`returned ${rows.length} of ${count} matching row(s)` + (clientSort ? `, sorted locally by ${a.sort}` : ''));
}

async function cmdPd(a) {
  if (a._[0] === 'list') {
    const list = await getJson(`${PD_API}/metastore/schemas/dataset/items?show-reference-ids=false`);
    const words = a.search ? String(a.search).toLowerCase().split(/\s+/) : [];
    const rows = list.map(d => ({ id: d.identifier, title: d.title }))
      .filter(d => words.every(w => d.title.toLowerCase().includes(w)))
      .sort((x, y) => x.title.localeCompare(y.title));
    emit(rows, a.format || 'json');
    log(`${rows.length} provider-data dataset(s)`);
    return;
  }
  const id = PD_ALIASES[a._[0]] || a._[0];
  if (!/^[a-z0-9]{4}-[a-z0-9]{4}$/.test(id || '')) die(`pd needs a provider-data dataset id like xubh-q36u (or alias: ${Object.keys(PD_ALIASES).join(', ')})`);
  const { base, title } = await dkanQueryBase(PD_API, id);
  // Provider-data values are text ("3", "Not Available"), so sort locally too.
  await runDkan(base, a, `provider-data ${id}${title ? ` (${title})` : ''} — large datasets take ~15s per request regardless of size; batch NPIs with --in`, PD_PAGE_SIZE, { clientSort: true });
}

// Open Payments (Sunshine Act): industry payments to physicians, NPPs and
// teaching hospitals. One dataset per program year per table; titles are
// stable ("2024 General Payment Data"), ids are not.
const OP_TYPES = {
  general:                   y => `${y} General Payment Data`,
  research:                  y => `${y} Research Payment Data`,
  ownership:                 y => `${y} Ownership Payment Data`,
  'recipient-entity':        y => `${y} payments grouped by covered recipient and reporting entities`,
  'recipient-nature':        y => `${y} payments grouped by covered recipient and nature of payments`,
  'entity-nature':           y => `${y} payments grouped by reporting entities and nature of payments`,
  'entity-recipient-nature': y => `${y} payments grouped by reporting entities, covered recipient, and nature of payments`,
  'state-nature':            y => `${y} state payment totals grouped by Nature of Payment for all years`,
  profile:                   () => 'Covered Recipient Profile Supplement',
  national:                  () => 'National level payment total and averages for all years',
  'national-specialty':      () => 'National level payment total and averages by provider specialty for all years',
  'teaching-hospitals':      () => 'Payments grouped by Teaching Hospital',
};

let opListMemo = null;
async function opList() {
  if (!opListMemo) opListMemo = await getJson(`${OP_API}/metastore/schemas/dataset/items?show-reference-ids`);
  return opListMemo;
}

async function cmdOp(a) {
  const type = a._[0];
  const list = await opList();
  const dist = d => (Array.isArray(d.distribution) && d.distribution[0] && d.distribution[0].identifier) || null;
  if (!type || type === 'list') {
    emit(list.map(d => ({ id: d.identifier, title: d.title })).sort((x, y) => x.title.localeCompare(y.title)), a.format || 'json');
    return;
  }
  let ds;
  if (UUID_RE.test(type)) {
    ds = list.find(d => d.identifier === type);
    if (!ds) die(`no Open Payments dataset with id ${type}. Run: node medtech-data.mjs op list`);
  } else {
    const mk = OP_TYPES[type];
    if (!mk) die(`unknown Open Payments table "${type}". Use one of: ${Object.keys(OP_TYPES).join(', ')}, list, or a dataset id`);
    const byTitle = t => list.find(d => d.title.toLowerCase() === t.toLowerCase());
    if (a.year) {
      ds = byTitle(mk(a.year));
      if (!ds) die(`no "${mk(a.year)}" dataset. Program years available: ${[...new Set(list.map(d => (d.title.match(/^(\d{4}) /) || [])[1]).filter(Boolean))].sort().join(', ')}`);
    } else {
      for (let y = new Date().getFullYear(); y >= 2013 && !ds; y--) ds = byTitle(mk(y));
      if (!ds) die(`no dataset found for "${type}"`);
    }
  }
  const base = dist(ds) ? `${OP_API}/datastore/query/${dist(ds)}` : (await dkanQueryBase(OP_API, ds.identifier)).base;
  // Open Payments stores amounts as text, so its server-side sort is alphabetical.
  await runDkan(base, a, `Open Payments — ${ds.title} (${ds.identifier})`, OP_PAGE_SIZE, { clientSort: true });
}

// openFDA device endpoints. No match → HTTP 404 {"error":{"code":"NOT_FOUND"}},
// which means zero results, not a failure. limit ≤ 1000, skip ≤ 25000.
const FDA_API = 'https://api.fda.gov';
const FDA_DEVICE = ['510k', 'pma', 'classification', 'recall', 'enforcement', 'event', 'udi', 'registrationlisting', 'covid19serology'];

// openFDA's `openfda` enrichment block repeats every registration/FEI number
// and every 510(k)/PMA for the whole product code (900+ entries on a recall),
// which has nothing to do with the record itself. Replace those arrays with
// a count unless --full.
const FDA_BULK = ['registration_number', 'fei_number', 'k_number', 'pma_number'];
export function stripFdaBulk(x) {
  if (Array.isArray(x)) return x.map(stripFdaBulk);
  if (!x || typeof x !== 'object') return x;
  const out = {};
  for (const [k, v] of Object.entries(x)) {
    if (k === 'openfda' && v && typeof v === 'object' && !Array.isArray(v)) {
      const kept = {};
      for (const [f, fv] of Object.entries(v)) {
        if (FDA_BULK.includes(f) && Array.isArray(fv)) kept[`${f}_count`] = fv.length;
        else kept[f] = stripFdaBulk(fv);
      }
      out[k] = kept;
    } else out[k] = stripFdaBulk(v);
  }
  return out;
}

// Recall `code_info` (lot/serial lists) can run to hundreds of KB per record.
// Truncate long strings visibly, never silently, unless --full.
const FDA_MAX_STR = 2000;
export function truncateLongStrings(x, max = FDA_MAX_STR) {
  if (typeof x === 'string') return x.length > max ? `${x.slice(0, max)}… [truncated ${x.length - max} more chars; use --full]` : x;
  if (Array.isArray(x)) return x.map(v => truncateLongStrings(v, max));
  if (x && typeof x === 'object') return Object.fromEntries(Object.entries(x).map(([k, v]) => [k, truncateLongStrings(v, max)]));
  return x;
}

async function cmdFda(a) {
  const ep = a._[0];
  if (!ep) die(`fda needs an endpoint: ${FDA_DEVICE.join(', ')} (device), or a full path like drug/label`);
  const path = FDA_DEVICE.includes(ep) ? `device/${ep}` : ep.replace(/\.json$/, '');
  if (!/^[a-z]+\/[a-z0-9]+$/.test(path)) die(`bad endpoint "${ep}"`);
  // openFDA wants spaces as '+'; ':' '"' '[' ']' stay readable.
  const q = s => encodeURIComponent(s).replace(/%20/g, '+').replace(/%2B/gi, '+').replace(/%3A/gi, ':').replace(/%22/g, '"').replace(/%5B/gi, '[').replace(/%5D/gi, ']');
  const params = [];
  if (a.search) params.push(`search=${q(a.search)}`);
  if (a.sort) params.push(`sort=${q(a.sort)}`);
  if (process.env.FDA_API_KEY) params.push(`api_key=${encodeURIComponent(process.env.FDA_API_KEY)}`);
  const mask = u => u.replace(/api_key=[^&]+/, 'api_key=***');
  const get = async url => {
    if (a.url) log(mask(url));
    try { return await getJson(url); } catch (e) {
      if (/HTTP 404/.test(e.message) && /NOT_FOUND|No matches/i.test(e.message)) return { results: [], meta: { results: { total: 0 } } };
      throw new Error(mask(e.message));
    }
  };
  if (a['count-by']) {
    const lim = Math.min(intArg(a.limit, 'limit', 100), 1000);
    const j = await get(`${FDA_API}/${path}.json?${[...params, `count=${q(a['count-by'])}`, `limit=${lim}`].join('&')}`);
    // openFDA ignores limit for date fields (one row per day), so cap here too.
    const all = j.results || [];
    emit(all.slice(0, lim), a.format || 'json');
    log(`${Math.min(all.length, lim)} of ${all.length} term(s) — openFDA ${path}, count=${a['count-by']}` +
        (all.length > lim ? ' (raise --limit for more; date fields count per day)' : ''));
    return;
  }
  const want = a.all ? Math.min(intArg(a.max, 'max', 5000), 26000) : intArg(a.limit, 'limit', 25);
  let skip = intArg(a.skip, 'skip', 0);
  const rows = [];
  let total = null;
  while (rows.length < want) {
    const limit = Math.min(1000, want - rows.length);
    if (skip > 25000) { log('warning: openFDA allows skip ≤ 25000; narrow --search to see more'); break; }
    const j = await get(`${FDA_API}/${path}.json?${[...params, `limit=${limit}`, `skip=${skip}`].join('&')}`);
    total = j.meta && j.meta.results ? j.meta.results.total : total;
    const page = j.results || [];
    rows.push(...page);
    skip += page.length;
    if (page.length < limit) break;
  }
  emit(a.full ? rows : truncateLongStrings(stripFdaBulk(rows)), a.format || 'json');
  log(`openFDA ${path} — returned ${rows.length} of ${total ?? 0} matching record(s)` + (total ? '' : ' (no matches)'));
}

// Census Bureau API. A key is required (requests without one redirect to
// missing_key.html). Free: https://api.census.gov/data/key_signup.html
const POP65_VARS = ['020', '021', '022', '023', '024', '025', '044', '045', '046', '047', '048', '049'].map(n => `B01001_${n}E`);

// Newest year whose dataset defines `probeVar`. The variables metadata
// endpoint needs no key (only data requests do), so this works keyless.
async function latestCensusYear(dataset, probeVar) {
  const now = new Date().getFullYear();
  for (let y = now - 1; y >= now - 6; y--) {
    try {
      await getJson(`https://api.census.gov/data/${y}/${dataset}/variables/${encodeURIComponent(probeVar)}.json`, { retries: 0 });
      return String(y);
    } catch { /* not published (404) — try the year before */ }
  }
  die(`variable ${probeVar} not found in any ${dataset} release from ${now - 6} to ${now - 1}: check the name (see api.census.gov/data/<year>/${dataset}/variables.html) or pass --year`);
}

async function cmdCensus(a) {
  const dataset = a.dataset || 'acs/acs5';
  const vars = a.pop65 ? ['NAME', 'B01001_001E', ...POP65_VARS] : String(a.get || '').split(',').map(s => s.trim()).filter(Boolean);
  if (!vars.length) die('census needs --get VAR1,VAR2 (or --pop65)');
  if (!a.for) die("census needs --for, e.g. --for 'state:*' or --for 'county:*' --in 'state:50'");
  const year = a.year ? String(a.year) : await latestCensusYear(dataset, vars.find(v => v !== 'NAME') || 'NAME');
  const key = process.env.CENSUS_API_KEY;
  if (!key) die(`the Census API requires a key for data requests (would query ${dataset} ${year}). ` +
    'Get a free one at https://api.census.gov/data/key_signup.html, activate it from the confirmation email, and set CENSUS_API_KEY');
  const params = [`get=${vars.map(encodeURIComponent).join(',')}`, `for=${encodeURIComponent(a.for)}`];
  if (a.in.length) params.push(...a.in.map(i => `in=${encodeURIComponent(i)}`));
  params.push(`key=${encodeURIComponent(key)}`);
  const url = `https://api.census.gov/data/${year}/${dataset}?${params.join('&')}`;
  if (a.url) log(url.replace(/key=[^&]+/, 'key=***'));
  let j;
  try { j = await getJson(url); } catch (e) {
    const msg = e.message.replace(/key=[^&\s]+/g, 'key=***');
    // A bad key redirects to an HTML "missing/invalid key" page rather than a JSON error.
    if (/missing_key|invalid[ _]key/i.test(msg)) die('Census rejected CENSUS_API_KEY (invalid, or not yet activated: use the link in the confirmation email). ' + msg.slice(0, 200));
    die(msg);
  }
  if (!Array.isArray(j) || !Array.isArray(j[0])) die('unexpected Census response shape');
  const [head, ...data] = j;
  let rows = data.map(r => Object.fromEntries(head.map((h, i) => [h, r[i]])));
  if (a.pop65) {
    rows = rows.map(r => {
      const geo = Object.fromEntries(Object.entries(r).filter(([k]) => !/^B01001_/.test(k)));
      return { ...geo, total_pop: +r.B01001_001E, pop_65_plus: POP65_VARS.reduce((s, v) => s + (+r[v] || 0), 0) };
    });
  }
  emit(rows, a.format || 'json');
  log(`Census ${dataset} ${year} — ${rows.length} row(s)`);
}

// ─── CENSUS POPULATION ESTIMATES (keyless) ───
// The Census Bureau's official annual estimates (PEP) as static CSVs on
// www2.census.gov: no API key, unlike api.census.gov. Layouts verified
// 2026-10-27 against the published file-layout PDFs (CC-EST2025-AGESEX,
// NC-EST2025-AGESEX-RES). County files are Latin-1 and hold county rows only
// (SUMLEV 050); a state total is the sum of its counties (checked: 50 states +
// DC sum exactly to the national file).
const POPEST_BASE = 'https://www2.census.gov/programs-surveys/popest/datasets';
const STATE_FIPS = {
  AL: '01', AK: '02', AZ: '04', AR: '05', CA: '06', CO: '08', CT: '09', DE: '10', DC: '11', FL: '12', GA: '13',
  HI: '15', ID: '16', IL: '17', IN: '18', IA: '19', KS: '20', KY: '21', LA: '22', ME: '23', MD: '24', MA: '25',
  MI: '26', MN: '27', MS: '28', MO: '29', MT: '30', NE: '31', NV: '32', NH: '33', NJ: '34', NM: '35', NY: '36',
  NC: '37', ND: '38', OH: '39', OK: '40', OR: '41', PA: '42', RI: '44', SC: '45', SD: '46', TN: '47', TX: '48',
  UT: '49', VT: '50', VA: '51', WA: '53', WV: '54', WI: '55', WY: '56', PR: '72',
};

// Minimal CSV parser (handles quoted fields, though PEP files have none).
export function parseCsv(text) {
  const rows = [];
  let row = [], field = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (c === '"') q = false;
      else field += c;
    } else if (c === '"') q = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); field = '';
      if (row.length > 1 || row[0] !== '') rows.push(row);
      row = [];
    } else field += c;
  }
  if (field !== '' || row.length) { row.push(field); rows.push(row); }
  const [header, ...data] = rows;
  return data.map(r => Object.fromEntries(header.map((h, i) => [h, r[i]])));
}

// County-file YEAR codes: 1 = 4/1/2020 base, 2 = 7/1/2020 … (vintage - 2018) = 7/1/vintage.
export function popestYearCode(year, vintage) {
  if (String(year).toLowerCase() === 'base') return 1;
  const y = Number(year);
  if (!Number.isInteger(y) || y < 2020 || y > vintage) return null;
  return y - 2018;
}

// Sum county rows (one YEAR) into a state total. Median age can't be summed.
export function sumPopestCounties(rows) {
  const n = k => rows.reduce((s, r) => s + (Number(r[k]) || 0), 0);
  return { total_pop: n('POPESTIMATE'), pop_65_plus: n('AGE65PLUS_TOT'), pop_85_plus: n('AGE85PLUS_TOT') };
}

// National file: single year of age, SEX 0 = total, AGE 999 = all ages, AGE 100 = 100+.
export function nationalFromSingleAge(rows, column) {
  const tot = rows.filter(r => r.SEX === '0');
  const n = pred => tot.filter(r => r.AGE !== '999' && pred(Number(r.AGE))).reduce((s, r) => s + Number(r[column]), 0);
  const all = tot.find(r => r.AGE === '999');
  return { total_pop: all ? Number(all[column]) : n(() => true), pop_65_plus: n(a => a >= 65), pop_85_plus: n(a => a >= 85) };
}

async function latestPopestVintage() {
  const html = await getText(`${POPEST_BASE}/`);
  const ranges = [...html.matchAll(/href="(\d{4})-(\d{4})\/"/g)].map(m => ({ dir: `${m[1]}-${m[2]}`, vintage: Number(m[2]) }));
  if (!ranges.length) die(`could not list vintages at ${POPEST_BASE}/ — the directory format may have changed`);
  return ranges.sort((x, y) => y.vintage - x.vintage)[0];
}

async function cmdPopest(a) {
  let v;
  if (a.vintage) {
    const vin = Number(a.vintage);
    v = { vintage: vin, dir: `${vin >= 2030 ? 2030 : 2020}-${vin}` };
  } else v = await latestPopestVintage();
  const year = a.year ? String(a.year) : String(v.vintage);
  const code = popestYearCode(year, v.vintage);
  if (!code) die(`--year must be 2020-${v.vintage} (or "base" for the April 1, 2020 estimates base) for vintage ${v.vintage}`);
  const label = year === 'base' ? 'April 1, 2020 estimates base' : `July 1, ${year}`;
  let rows, src;
  if (!a.state) {
    if (a.county || a.fips || a['by-county']) die('county-level needs --state XX');
    src = `${POPEST_BASE}/${v.dir}/national/asrh/nc-est${v.vintage}-agesex-res.csv`;
    const data = parseCsv(await getText(src, { encoding: 'latin1' }));
    const col = year === 'base' ? 'ESTIMATESBASE2020' : `POPESTIMATE${year}`;
    if (!data.length || !(col in data[0])) die(`national file has no ${col} column — ${src}`);
    rows = [{ level: 'National', state: 'US', county: '', fips: '', ...nationalFromSingleAge(data, col) }];
  } else {
    const st = String(a.state).toUpperCase();
    const fips = STATE_FIPS[st];
    if (!fips) die(`unknown state "${a.state}" — use a 2-letter postal code (incl. DC, PR)`);
    src = `${POPEST_BASE}/${v.dir}/counties/asrh/cc-est${v.vintage}-agesex-${fips}.csv`;
    let data = parseCsv(await getText(src, { encoding: 'latin1' })).filter(r => r.YEAR === String(code));
    if (!data.length) die(`no rows for YEAR code ${code} in ${src}`);
    const stname = data[0].STNAME;
    if (a.fips) data = data.filter(r => `${r.STATE}${r.COUNTY}` === String(a.fips).padStart(5, '0'));
    if (a.county) data = data.filter(r => r.CTYNAME.toLowerCase().startsWith(String(a.county).toLowerCase()));
    if ((a.fips || a.county) && !data.length) die(`no county matching ${a.fips || a.county} in ${stname}`);
    if (a.county || a.fips || a['by-county']) {
      rows = data.map(r => ({
        level: 'County', state: st, county: r.CTYNAME, fips: `${r.STATE}${r.COUNTY}`,
        total_pop: Number(r.POPESTIMATE), pop_65_plus: Number(r.AGE65PLUS_TOT), pop_85_plus: Number(r.AGE85PLUS_TOT),
        median_age: Number(r.MEDIAN_AGE_TOT),
      }));
    } else {
      rows = [{ level: 'State', state: st, county: '', fips, ...sumPopestCounties(data) }];
    }
  }
  rows = rows.map(r => ({ ...r, year, pct_65_plus: r.total_pop ? +(r.pop_65_plus / r.total_pop * 100).toFixed(2) : null }));
  emit(rows, a.format || 'json');
  log(`Census Bureau Population Estimates (PEP), Vintage ${v.vintage}, resident population ${label} — ${rows.length} row(s). Source: ${src}`);
}

// Medicare Monthly Enrollment → Original Medicare (FFS) vs MA share. One
// rolling dataset: the data year is the YEAR column (not --year on `query`),
// and MONTH="Year" marks the annual row.
async function cmdFfsShare(a) {
  const r = await resolveDataset('enrollment');
  if (a.state && String(a.state).toUpperCase() === 'US') delete a.state; // national
  const lvl = a.county || a.fips || a['by-county'] ? 'County' : a.state ? 'State' : 'National';
  const conds = [{ path: 'BENE_GEO_LVL', op: '=', value: lvl }];
  if (a.state) conds.push({ path: 'BENE_STATE_ABRVTN', op: '=', value: String(a.state).toUpperCase() });
  if (a.county) conds.push({ path: 'BENE_COUNTY_DESC', op: 'STARTS_WITH', value: a.county }); // stored as "Windham County"
  if (a.fips) conds.push({ path: 'BENE_FIPS_CD', op: '=', value: a.fips });
  if ((a.county || a['by-county']) && !a.state && !a.fips) die('county-level needs --state XX (plus --county NAME, or --by-county for all counties)');
  const cols = 'YEAR,MONTH,BENE_GEO_LVL,BENE_STATE_ABRVTN,BENE_STATE_DESC,BENE_COUNTY_DESC,BENE_FIPS_CD,TOT_BENES,ORGNL_MDCR_BENES,MA_AND_OTH_BENES';
  const fetchRows = async (extra, size) => {
    const url = `${DATA_API}/${r.id}/data?${[buildDataApiFilter([...conds, ...extra]), `column=${cols}`, 'sort=-YEAR', `size=${size}`].join('&')}`;
    if (a.url) log(url);
    return getJson(url);
  };
  let year = a.year;
  if (!year) {
    const latest = await fetchRows([{ path: 'MONTH', op: '=', value: 'Year' }], 1);
    if (!latest.length) die('no annual (MONTH=Year) enrollment rows match');
    year = latest[0].YEAR;
  }
  let rows = await fetchRows([{ path: 'YEAR', op: '=', value: String(year) }, { path: 'MONTH', op: '=', value: 'Year' }], 5000);
  let period = `${year} annual row`;
  if (!rows.length) die(`no annual enrollment row for ${year}${a.year ? ' (the current year has monthly rows only; omit --year for the latest full year)' : ''}`);
  rows = rows.map(x => {
    const tot = +x.TOT_BENES, ffs = +x.ORGNL_MDCR_BENES, ma = +x.MA_AND_OTH_BENES;
    return {
      year: x.YEAR, level: x.BENE_GEO_LVL, state: x.BENE_STATE_ABRVTN, state_name: x.BENE_STATE_DESC,
      county: x.BENE_COUNTY_DESC, fips: x.BENE_FIPS_CD, total_benes: tot, original_medicare_benes: ffs,
      ma_and_other_benes: ma, ffs_share: tot ? +(ffs / tot).toFixed(4) : null, ma_share: tot ? +(ma / tot).toFixed(4) : null,
    };
  });
  emit(rows, a.format || 'json');
  log(`Medicare Monthly Enrollment (${r.id}) — ${period}, ${lvl} level, ${rows.length} row(s). ` +
      'ffs_share = Original Medicare / total; MA_AND_OTH includes MA and other non-FFS plans (cost plans, PACE).');
}

// NPPES returns HTTP 200 with {"Errors":[...]} for bad input — treat as error.
async function cmdNpi(a) {
  const allowed = ['number', 'enumeration_type', 'taxonomy_description', 'first_name', 'last_name',
    'organization_name', 'city', 'state', 'postal_code', 'country_code', 'address_purpose', 'use_first_name_alias', 'name_purpose'];
  const params = new URLSearchParams({ version: '2.1' });
  for (const k of allowed) if (a[k] !== undefined) params.set(k, a[k]);
  const want = intArg(a.limit, 'limit', 10);
  let skip = intArg(a.skip, 'skip', 0);
  const rows = [];
  while (rows.length < want) {
    const limit = Math.min(200, want - rows.length); // NPPES silently caps limit at 200
    params.set('limit', limit); params.set('skip', skip);
    const url = `${NPPES_API}?${params}`;
    if (a.url) log(url);
    const j = await getJson(url);
    if (j.Errors) die(`NPPES rejected the query: ${j.Errors.map(e => `${e.field}: ${e.description}`).join('; ')}`);
    const page = j.results || [];
    rows.push(...page);
    skip += page.length;
    if (page.length < limit) break;
  }
  const flat = a.raw ? rows : rows.map(r => {
    const b = r.basic || {};
    const loc = (r.addresses || []).find(x => x.address_purpose === 'LOCATION') || {};
    const tax = (r.taxonomies || []).find(t => t.primary) || (r.taxonomies || [])[0] || {};
    return {
      npi: r.number, type: r.enumeration_type,
      name: b.organization_name || [b.first_name, b.middle_name, b.last_name].filter(Boolean).join(' '),
      credential: b.credential || '', status: b.status || '',
      taxonomy: tax.desc || '', taxonomy_code: tax.code || '', license_state: tax.state || '',
      address: [loc.address_1, loc.address_2].filter(Boolean).join(' '), city: loc.city || '',
      state: loc.state || '', zip: (loc.postal_code || '').slice(0, 5), phone: loc.telephone_number || '',
      last_updated: b.last_updated || '',
    };
  });
  emit(flat, a.format || 'json');
  log(`returned ${rows.length} record(s)` + (rows.length === want ? ' (more may exist — NPPES gives no total)' : ''));
}

const HELP = `medtech-data.mjs — query CMS, NPPES, Open Payments, openFDA and Census APIs (Node 18+, no dependencies)

DATA-API (Medicare claims datasets on data.cms.gov/data-api)
  datasets [--search words] [--refresh]       list dataset families + years (from data.json)
  versions <dataset>                          year → UUID for one family
  columns  <dataset> [--year Y]               exact column names (filters are case-sensitive)
  query    <dataset> [options]                fetch rows
      --year Y            data year (default: newest)
      --where 'Col=val'   repeatable; ops: =  !=  ~ (contains)  ^ (starts with)  > >= < <=
      --in 'Col=a,b,c'    repeatable; IN list
      --columns a,b,c     return only these columns
      --sort [-]Col       sort (numeric columns sort numerically); '-' = descending
      --limit N           rows to return (default 100)   --offset N
      --all [--max N]     page through everything (default max 50000)
      --count             print matching row count only (no rows)
  <dataset> = alias (${Object.keys(FAMILIES).join(', ')}),
              a catalog title or unique fragment of one, or a dataset UUID

PROVIDER DATA CATALOG (data.cms.gov/provider-data)
  pd list [--search words]                    browse all ~240 provider-data datasets (Care Compare etc.)
  pd <id|alias> [--where 'prop=val'] [--in 'npi=1,2,3'] [--columns a,b] [--sort [-]prop] [--limit N] [--all]
      aliases: clinicians=mj5m-pzi6  facilityAff=27ea-46a8  hospitals=xubh-q36u
      ~ means case-insensitive LIKE %text%

MEDICARE ENROLLMENT (FFS vs Medicare Advantage share)
  ffs-share [--state XX [--county NAME | --fips NNNNN | --by-county]] [--year YYYY]
      latest full year by default; ffs_share = Original Medicare / total beneficiaries

OPEN PAYMENTS (openpaymentsdata.cms.gov — industry payments to clinicians)
  op list                                     all tables and their ids
  op <table> [--year Y] [--where/--in/--columns/--sort/--limit/--all/--count]
      tables: ${Object.keys(OP_TYPES).join(', ')}
      exact '=' on NPI/ids is fast (~2s); '~' (contains) on 'general' is slow (~30s)

OPENFDA (api.fda.gov — devices)
  fda <endpoint> [--search 'field:value AND ...'] [--count-by field.exact] [--sort field:desc]
                 [--limit N] [--skip N] [--all [--max N]] [--full]
      endpoints: ${FDA_DEVICE.join(', ')} (or e.g. drug/label)
      no match = empty result (openFDA's 404); --full keeps openfda's bulk arrays and long text untruncated
      optional FDA_API_KEY env var raises rate limits

CENSUS POPULATION ESTIMATES (www2.census.gov — no key)
  popest [--state XX [--county NAME | --fips NNNNN | --by-county]] [--year YYYY|base] [--vintage YYYY]
      official annual resident population: total, 65+, 85+ (+ median age for counties); newest vintage by default

CENSUS ACS (api.census.gov — requires free CENSUS_API_KEY)
  census --get VARS --for 'county:*' [--in 'state:50'] [--year Y] [--dataset acs/acs5]
      --year defaults to the newest release that defines the first variable
  census --pop65 --for 'state:*'              total and 65+ population (ACS B01001)

NPPES NPI REGISTRY
  npi [--number N] [--first_name X] [--last_name X] [--organization_name X] [--state XX]
      [--city X] [--postal_code X] [--taxonomy_description X] [--enumeration_type NPI-1|NPI-2]
      [--limit N] [--skip N] [--raw]
      Trailing * wildcard allowed after 2+ chars (e.g. --last_name 'smi*').
      --state alone is rejected; pair it with another criterion.

COMMON
  --format json|csv|ndjson   (default json)     --url   print each request URL to stderr
`;

async function main() {
  const [cmd, ...rest] = process.argv.slice(2);
  const a = parseArgs(rest);
  if (!cmd || cmd === 'help' || a.help) { process.stdout.write(HELP); return; }
  const cmds = { datasets: cmdDatasets, versions: cmdVersions, columns: cmdColumns, query: cmdQuery, pd: cmdPd, npi: cmdNpi, op: cmdOp, fda: cmdFda, census: cmdCensus, popest: cmdPopest, 'ffs-share': cmdFfsShare };
  if (!cmds[cmd]) die(`unknown command "${cmd}". Run: node medtech-data.mjs help`);
  await cmds[cmd](a);
}

const isMain = (() => {
  try { return !!process.argv[1] && realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url)); } catch { return false; }
})();
if (isMain) { reexecWithEnvProxy(); main().catch(e => die(e.message)); }
